mkdir -p scratch/grayWolf && cat > scratch/grayWolf/run.ts <<'EOF'
import * as THREE from "three";
import build from "../../samples/grayWolf";
const root = build();
let meshes = 0, tris = 0, joints = 0;
root.traverse((o: any) => { if (o.isMesh) { meshes++; const g = o.geometry; tris += (g.index ? g.index.count : g.attributes.position.count) / 3; } if (o.isBone || o.userData?.joint) joints++; });
const box = new THREE.Box3().setFromObject(root, true);
console.log({ meshes, tris, size: box.getSize(new THREE.Vector3()), min: box.min, max: box.max });
EOF
npx tsx scratch/grayWolf/run.ts 2>&1 | tail -30
